<script setup lang="ts">import {fmt} from '../utils/format';import Table from './common/Table.vue';defineProps<{profile:any}>();</script><template><section class="profile-matrix"><div class="section-head"><h2>{{profile.name}} / {{profile.version}}</h2><span>固定参数 / 不做EM</span></div><p>π：{{profile.parameters.pi.map(v=>fmt(v,8)).join(' / ')}}<br/>状态顺序 {{profile.states.join(' / ')}}</p><div class="matrix-layout"><Table :headers="['A 转移',...profile.states]"><tr v-for="(row,i) in profile.parameters.transition" :key="i"><td>{{profile.states[i]}}</td><td v-for="(v,j) in row" :key="j" :class="{zero:v===0}">{{fmt(v,8)}}</td></tr></Table><Table :headers="['B 发射',...profile.symbols]"><tr v-for="(row,i) in profile.parameters.emission" :key="i"><td>{{profile.states[i]}}</td><td v-for="(v,j) in row" :key="j" :class="{zero:v===0}">{{fmt(v,8)}}</td></tr></Table></div><details><summary>行和容差归一记录 / 真实0不加epsilon</summary><p>容差{{profile.parameters.sum_tolerance}}；超出即拒绝。归一只除以该行原始和。</p><div v-for="(r,i) in profile.parameters.normalization" :key="i" class="normalization-row">{{r.field}}[{{r.row}}] 原和 {{r.original_sum}} / delta {{r.delta_from_one===0?'0':r.delta_from_one.toExponential(4)}} / {{r.renormalized?'已归一':'无需归一'}}</div></details></section></template>
